export const ONBOARDING_SLIDES = {
  pt:[{title:'Descobre monumentos interessantes',body:'Na tua cidade existem muitos monumentos históricos que te podem interessar pela sua história.'},{title:'Digitaliza um monumento',body:'Lê ou ouve uma história fascinante que não vais ouvir numa visita guiada.\n\nAponta a câmara para o objeto e aguarda o carregamento da história.'},{title:'Encontra rotas',body:'Vamos propor-te rotas adaptadas às tuas preferências.\n\nTraçamos o caminho até ao ponto desejado, e podes descobrir a história como numa aventura.'},{title:'Partilha a tua história',body:'Ajuda outros utilizadores a descobrir locais e histórias interessantes. Publica posts e stories com uma rota.'},{title:'Conversa com os teus amigos',body:'Encontra rotas interessantes, partilha-as com os teus amigos e façam passeios juntos.\n\nCriem a vossa própria excursão entre amigos.'},{title:'KRAЇNA',body:'— A história está onde tu estás agora'}],
  cs:[{title:'Objevuj zajímavé památky',body:'Ve tvém městě jsou mnohé historické památky, které tě mohou zaujmout svým příběhem.'},{title:'Naskenuj památku',body:'Přečti si nebo poslechni zajímavý příběh, který neuslyšíš při prohlídce.\n\nNamiř kameru na objekt a vyčkej načtení příběhu.'},{title:'Hledej trasy',body:'Navrhneme ti trasy přizpůsobené tvým preferencím.\n\nVyznačíme cestu k požadovanému bodu, a ty můžeš objevovat historii jako ve hře.'},{title:'Sdílej svůj příběh',body:'Pomoz ostatním uživatelům objevovat zajímavá místa a příběhy. Sdílej příspěvky a stories s trasou.'},{title:'Povídej si s přáteli',body:'Najdi zajímavé trasy, sdílej je s přáteli a vyrazte společně na procházku.\n\nVytvořte si vlastní výpravu s přáteli.'},{title:'KRAЇNA',body:'— Historie je tam, kde právě jsi'}],
  sk:[{title:'Objavuj zaujímavé pamiatky',body:'Vo tvojom meste sú mnohé historické pamiatky, ktoré ťa môžu zaujať svojím príbehom.'},{title:'Naskenuj pamiatku',body:'Prečítaj si alebo počúvaj zaujímavý príbeh, ktorý nepočuješ pri prehliadke.\n\nNamieru kameru na objekt a vyčkaj načítanie príbehu.'},{title:'Hľadaj trasy',body:'Navrhneme ti trasy prispôsobené tvojim preferenciám.\n\nVyznačíme cestu k požadovanému bodu, a ty môžeš objavovať históriu ako v hre.'},{title:'Zdieľaj svoj príbeh',body:'Pomôž ostatným užívateľom objavovať zajímavé miesta a príbehy. Zdieľaj príspevky a stories s trasou.'},{title:'Rozprávaj sa s priateľmi',body:'Nájdi zaujímavé trasy, zdieľaj ich s priateľmi a vyrazte spolu na prechádzku.\n\nVytvorte si vlastnú výpravu s priateľmi.'},{title:'KRAЇNA',body:'— História je tam, kde práve si'}],
  hu:[{title:'Fedezz fel érdekes emlékműveket',body:'A városodban sok történelmi műemlék található, amelyek történetükkel érdekelhetnek.'},{title:'Szkennelj egy emlékművet',body:'Olvass vagy hallgass meg egy érdekes történetet, amit idegenvezetésen nem fogsz hallani.\n\nIrányítsd a kamerát az objektumra, és várd meg, míg betöltődik a történet.'},{title:'Keress útvonalakat',body:'Olyan útvonalakat ajánlunk, amelyek a preferenciáidhoz igazodnak.\n\nKirajzoljuk az utat a kívánt pontig, és felfedezed a történelmet, mint egy kalandban.'},{title:'Oszd meg a saját történeted',body:'Segíts más felhasználóknak érdekes helyeket és történeteket felfedezni. Oszd meg posztjaidat és storykat útvonallal.'},{title:'Beszélgess a barátaiddal',body:'Találj érdekes útvonalakat, oszd meg őket a barátaiddal, és induljatok el együtt sétálni.\n\nAlkossatok közös kirándulást a barátokkal.'},{title:'KRAЇNA',body:'— A történelem ott van, ahol te most vagy'}],
  sv:[{title:'Upptäck intressanta monument',body:'I din stad finns många historiska monument som kan intressera dig med sin historia.'},{title:'Skanna ett monument',body:'Läs eller lyssna på en intressant historia som du inte hör på en guidad tur.\n\nRikta kameran mot objektet och vänta på att historien laddas.'},{title:'Hitta rutter',body:'Vi föreslår rutter anpassade efter dina preferenser.\n\nVi kartlägger vägen till den önskade punkten, och du kan upptäcka historien som i ett äventyr.'},{title:'Dela din historia',body:'Hjälp andra användare att upptäcka intressanta platser och historier. Dela inlägg och stories med en rutt.'},{title:'Chatta med dina vänner',body:'Hitta intressanta rutter, dela dem med dina vänner och gå ut och promenera tillsammans.\n\nSkapa er egen utflykt med vänner.'},{title:'KRAЇNA',body:'— Historien är där du är just nu'}],
  no:[{title:'Oppdag interessante monumenter',body:'I byen din finnes mange historiske monumenter som kan interessere deg med sin historie.'},{title:'Skann et monument',body:'Les eller lytt til en interessant historie som du ikke hører på en guidet tur.\n\nRett kameraet mot objektet og vent på at historien lastes.'},{title:'Finn ruter',body:'Vi foreslår ruter tilpasset dine preferanser.\n\nVi tegner veien til det ønskede punktet, og du kan oppdage historien som i et eventyr.'},{title:'Del din historie',body:'Hjelp andre brukere med å oppdage interessante steder og historier. Del innlegg og stories med en rute.'},{title:'Chat med vennene dine',body:'Finn interessante ruter, del dem med vennene dine og gå ut og gå sammen.\n\nLag deres egen utflukt med venner.'},{title:'KRAЇNA',body:'— Historien er der du er nå'}],
  da:[{title:'Opdag interessante monumenter',body:'I din by findes mange historiske monumenter, der kan interessere dig med deres historie.'},{title:'Skan et monument',body:'Læs eller lyt til en interessant historie, som du ikke hører på en guidet tur.\n\nRet kameraet mod objektet og vent på, at historien indlæses.'},{title:'Find ruter',body:'Vi foreslår ruter tilpasset dine præferencer.\n\nVi tegner vejen til det ønskede punkt, og du kan opdage historien som i et eventyr.'},{title:'Del din historie',body:'Hjælp andre brugere med at opdage interessante steder og historier. Del opslag og stories med en rute.'},{title:'Chat med dine venner',body:'Find interessante ruter, del dem med dine venner og gå ud og gå sammen.\n\nSkab jeres egen udflugt med venner.'},{title:'KRAЇNA',body:'— Historien er, hvor du er nu'}],
  fi:[{title:'Löydä kiinnostavia monumentteja',body:'Kaupungissasi on monia historiallisia monumentteja, jotka voivat kiinnostaa sinua tarinallaan.'},{title:'Skannaa monumentti',body:'Lue tai kuuntele mielenkiintoinen tarina, jota et kuule opastetulla kierroksella.\n\nOsoita kamera kohteeseen ja odota tarinan latautumista.'},{title:'Etsi reittejä',body:'Ehdotamme reittejä, jotka on mukautettu mieltymyksiisi.\n\nKartoitamme reitin haluamaasi pisteeseen, ja voit löytää historian kuin seikkailussa.'},{title:'Jaa tarinasi',body:'Auta muita käyttäjiä löytämään kiinnostavia paikkoja ja tarinoita. Jaa julkaisuja ja storyjä reitin kanssa.'},{title:'Keskustele kavereidesi kanssa',body:'Löydä kiinnostavia reittejä, jaa ne kavereidesi kanssa ja lähtekää ulos kävelemään yhdessä.\n\nLuokaa oma retki ystävien kanssa.'},{title:'KRAЇNA',body:'— Historia on siellä, missä sinä olet nyt'}],
  is:[{title:'Uppgötvaðu áhugaverð minnismerki',body:'Í borginni þinni eru mörg söguleg minnismerki sem geta vakið áhuga þinn með sögu sinni.'},{title:'Skannaðu minnismerki',body:'Lestu eða hlustaðu á áhugaverða sögu sem þú munt ekki heyra á skipulagðri ferð.\n\nBeinttu myndavélinni að hlutnum og bíddu eftir að sagan hlaðist.'},{title:'Finndu leiðir',body:'Við leggjum til leiðir sem eru aðlagaðar að óskum þínum.\n\nVið kortleggjum leiðina að viðkomandi stað, og þú getur uppgötvað söguna eins og í ævintýri.'},{title:'Deildu sögu þinni',body:'Hjálpaðu öðrum notendum að uppgötva áhugaverða staði og sögur. Deildu færslum og stories með leið.'},{title:'Spjallaðu við vini þína',body:'Finndu áhugaverðar leiðir, deildu þeim með vinum þínum og farið út að ganga saman.\n\nBúið til ykkar eigin ferð með vinum.'},{title:'KRAЇNA',body:'— Sagan er þar sem þú ert núna'}],
  et:[{title:'Avasta huvitavaid mälestusmärke',body:'Sinu linnas on palju ajaloolisi mälestusmärke, mis võivad sind oma looga huvitada.'},{title:'Skanni mälestusmärk',body:'Loe või kuula huvitavat lugu, mida giidiekskursioonil ei kuule.\n\nSuuna kaamera objektile ja oota loo laadimist.'},{title:'Otsi marsruute',body:'Pakume sulle marsruute, mis on kohandatud sinu eelistuste järgi.\n\nMe joonistame tee soovitud punktini ja saad ajalugu avastada nagu seikluses.'},{title:'Jaga oma lugu',body:'Aita teistel kasutajatel avastada huvitavaid kohti ja lugusid. Jaga postitusi ja storysid koos marsruudiga.'},{title:'Vestle sõpradega',body:'Leia huvitavaid marsruute, jaga neid sõpradega ja minge koos jalutama.\n\nLooge oma sõpradega oma ekskursioon.'},{title:'KRAЇNA',body:'— Ajalugu on seal, kus sa praegu oled'}],
  el:[{title:'Ανακάλυψε ενδιαφέροντα μνημεία',body:'Στην πόλη σου υπάρχουν πολλά ιστορικά μνημεία που μπορούν να σε ενδιαφέρουν με την ιστορία τους.'},{title:'Σκανάρισε ένα μνημείο',body:'Διάβασε ή άκουσε μια ενδιαφέρουσα ιστορία που δεν θα ακούσεις σε μια ξενάγηση.\n\nΣτόχευσε την κάμερα στο αντικείμενο και περίμενε να φορτωθεί η ιστορία.'},{title:'Βρες διαδρομές',body:'Θα σου προτείνουμε διαδρομές προσαρμοσμένες στις προτιμήσεις σου.\n\nΘα χαράξουμε τη διαδρομή μέχρι το επιθυμητό σημείο, και μπορείς να ανακαλύψεις την ιστορία σαν σε μια περιπέτεια.'},{title:'Μοιράσου την ιστορία σου',body:'Βοήθησε άλλους χρήστες να ανακαλύψουν ενδιαφέροντα μέρη και ιστορίες. Μοιράσου αναρτήσεις και stories με διαδρομή.'},{title:'Συνόμιλησε με τους φίλους σου',body:'Βρες ενδιαφέρουσες διαδρομές, μοιράσου τις με τους φίλους σου και βγείτε να περπατήσετε μαζί.\n\nΔημιουργήστε τη δική σας εκδρομή με φίλους.'},{title:'KRAЇNA',body:'— Η ιστορία είναι εκεί που βρίσκεσαι τώρα'}],
  bg:[{title:'Открий интересни паметници',body:'В твоя град има много исторически паметници, които могат да те заинтересуват със своята история.'},{title:'Сканирай паметник',body:'Прочети или чуй интересна история, която няма да чуеш в екскурзия.\n\nНасочи камерата към обекта и изчакай зареждането на историята.'},{title:'Търси маршрути',body:'Ще ти предложим маршрути, адаптирани към твоите предпочитания.\n\nЩе начертаем пътя до желаната точка, и можеш да откриеш историята като в приключение.'},{title:'Сподели своята история',body:'Помогни на други потребители да открият интересни места и истории. Сподели публикации и stories с маршрут.'},{title:'Чатни с приятели',body:'Намери интересни маршрути, сподели ги с приятели и излезте да се разходите заедно.\n\nСъздайте своя екскурзия с приятели.'},{title:'KRAЇNA',body:'— Историята е там, където си сега'}],
  hr:[{title:'Otkrij zanimljive spomenike',body:'U tvom gradu postoje brojni povijesni spomenici koji te mogu zanimati svojom pričom.'},{title:'Skeniraj spomenik',body:'Pročitaj ili poslušaj zanimljivu priču koju nećeš čuti na vođenoj turi.\n\nUsmjeri kameru na objekt i pričekaj učitavanje priče.'},{title:'Traži rute',body:'Predložit ćemo ti rute prilagođene tvojim preferencijama.\n\nUcrtati ćemo put do željene točke, i možeš otkriti povijest kao u pustolovini.'},{title:'Podijeli svoju priču',body:'Pomogni drugim korisnicima da otkriju zanimljiva mjesta i priče. Dijeli objave i storyje s rutom.'},{title:'Razgovaraj s prijateljima',body:'Pronađi zanimljive rute, podijeli ih s prijateljima i izađite zajedno u šetnju.\n\nStvorite vlastitu ekskurziju s prijateljima.'},{title:'KRAЇNA',body:'— Povijest je tamo gdje si sada'}],
  sl:[{title:'Odkrivaj zanimive spomenike',body:'V tvojem mestu je veliko zgodovinskih spomenikov, ki te lahko zanimajo s svojo zgodbo.'},{title:'Skeniraj spomenik',body:'Preberi ali poslušaj zanimivo zgodbo, ki je ne boš slišal na vodenem ogledu.\n\nUsmeri kamero na objekt in počakaj, da se zgodba naloži.'},{title:'Išči poti',body:'Predlagali ti bomo poti, prilagojene tvojim željam.\n\nNačrtali bomo pot do želene točke, in lahko odkrivaš zgodovino kot v pustolovščini.'},{title:'Deli svojo zgodbo',body:'Pomagaj drugim uporabnikom odkrivati zanimiva mesta in zgodbe. Objavljaj objave in storije s potjo.'},{title:'Klepetaj s prijatelji',body:'Najdi zanimive poti, deli jih s prijatelji in pojdite skupaj na sprehod.\n\nUstvarite svoj izlet s prijatelji.'},{title:'KRAЇNA',body:'— Zgodovina je tam, kjer si zdaj'}],
  sr:[{title:'Открij занимљиве споменике',body:'У твом граду постоје многобројни историјски споменици који те могу занимати својом причом.'},{title:'Скенирај споменик',body:'Прочитај или слушај занимљиву причу коју нећеш чути на вођеној тури.\n\nУсмери камеру на објекат и сачекај учитавање приче.'},{title:'Тражи руте',body:'Предложићемо ти руте прилагођене твојим преференцијама.\n\nУцртаћемо пут до жељене тачке, и можеш открити историју као у авантури.'},{title:'Подели своју причу',body:'Помози другим корисницима да открију занимљива места и приче. Дели објаве и stories са рутом.'},{title:'Ћаскај са пријатељима',body:'Пронађи занимљиве руте, подели их са пријатељима и изађите заједно у шетњу.\n\nНапавите сопствену екскурзију са пријатељима.'},{title:'KRAЇNA',body:'— Историја је тамо где си сада'}],
  bs:[{title:'Otkrij zanimljive spomenike',body:'U tvom gradu postoje brojni historijski spomenici koji te mogu zanimati svojom pričom.'},{title:'Skeniraj spomenik',body:'Pročitaj ili slušaj zanimljivu priču koju nećeš čuti na vođenoj turi.\n\nUsmjeri kameru na objekat i sačekaj učitavanje priče.'},{title:'Traži rute',body:'Predložit ćemo ti rute prilagođene tvojim preferencijama.\n\nUcrtati ćemo put do željene tačke, i možeš otkriti historiju kao u avanturi.'},{title:'Podijeli svoju priču',body:'Pomogni drugim korisnicima da otkriju zanimljiva mjesta i priče. Dijeli objave i storije sa rutom.'},{title:'Razgovaraj sa prijateljima',body:'Pronađi zanimljive rute, podijeli ih sa prijateljima i izađite zajedno u šetnju.\n\nNapravite svoju ekskurziju sa prijateljima.'},{title:'KRAЇNA',body:'— Historija je tamo gdje si sada'}],
  mk:[{title:'Откриј интересни споменици',body:'Во твојот град има многу историски споменици кои можат да те интересираат со својата приказна.'},{title:'Скенирај споменик',body:'Прочитај или слушни интересна приказна која нема да ја слушнеш на водена тура.\n\nНасочи ја камерата кон објектот и почекај да се вчита приказната.'},{title:'Барај рути',body:'Ќе ти предложиме рути прилагодени на твоите преференции.\n\nЌе ја обележиме патеката до саканата точка, и можеш да ја откриеш историјата како во авантура.'},{title:'Сподели ја твојата приказна',body:'Помогни им на другите корисници да откриваат интересни места и приказни. Сподели објави и stories со рута.'},{title:'Разговарај со пријателите',body:'Најди интересни рути, сподели ги со пријателите и излезете заедно на прошетка.\n\nСоздадете своја екскурзија со пријатели.'},{title:'KRAЇNA',body:'— Историјата е таму каде што си сега'}],
  sq:[{title:'Zbulon monumente interesante',body:'Në qytetin tënd ka shumë monumente historike që mund të të interesojnë me historinë e tyre.'},{title:'Skanoj një monument',body:'Lexo ose dëgjo një histori interesante që nuk do ta dëgjosh në një tur me udhërrëfyes.\n\nDrejto kamerën drejt objektit dhe prit që historia të ngarkohet.'},{title:'Gjej rrugë',body:'Do të të propozojmë rrugë të përshtatura me preferencat e tua.\n\nDo të vizatojmë rrugën deri te pika e dëshiruar, dhe mund të zbulosh historinë si në një aventurë.'},{title:'Ndaj historinë tënde',body:'Ndihmoji përdoruesit e tjerë të zbulojnë vende dhe histori interesante. Ndaj postime dhe stories me një rrugë.'},{title:'Bisedo me miqtë',body:'Gjej rrugë interesante, ndaji ato me miqtë dhe dilni të ecni bashkë.\n\nKrijoji udhëtimin tuaj me miqtë.'},{title:'KRAЇNA',body:'— Historia është atje ku je tani'}],

  mt:[{title:'Skopri monumenti interessanti',body:'Fil-belt tiegħek hemm ħafna monumenti storiċi li jistgħu jinteressawk bl-istorja tagħhom.'},{title:'Skennja monument',body:'Aqra jew isma\' storja interessanti li ma tismax fuq tour guidat.\n\nPoġġi l-kamera lejn l-oġġett u stenna li l-istorja tiġi karikta.'},{title:'Sib rotot',body:'Se nipproponu rotot adattati għall-preferenzi tiegħek.\n\nNiddisinjaw it-triq sal-punt mixtieq, u tista\' tiskopri l-istorja bħal f\'avventura.'},{title:'Aqsam l-istorja tiegħek',body:'Għin lill-utenti oħra jiskopru postijiet u stejjer interessanti. Aqsam posts u stories bi rotta.'},{title:'Ċettja mal-ħbieb',body:'Sib rotot interessanti, aqsamhom mal-ħbieb u oħorġu timxu flimkien.\n\nOħolqu l-gita tagħkom mal-ħbieb.'},{title:'KRAЇNA',body:'— L-istorja hija fejn int issa'}],
  ga:[{title:'Aimsigh séadchomharthaí suimiúla',body:'I do chathair tá go leor séadchomharthaí stairiúla a d\'fhéadfadh suim a bheith agat iontu lena scéal.'},{title:'Scan séadchomhartha',body:'Léigh nó éist le scéal suimiúil nach gcloisfidh tú ar thuras treoraithe.\n\nDírigh an ceamara ar an réad agus fan go luchtófar an scéal.'},{title:'Faigh bealaí',body:'Molfaimid bealaí duit atá oiriúnach do do chuid roghanna.\n\nTarraingeoimid an bealach go dtí an pointe is mian leat, agus is féidir leat an stair a fháil amach cosúil le heachtra.'},{title:'Roinn do scéal',body:'Cabhraigh le húsáideoirí eile áiteanna agus scéalta suimiúla a fháil. Roinn postanna agus stories le bealach.'},{title:'Comhrá le cairde',body:'Faigh bealaí suimiúla, roinn iad le cairde agus téigí amach ag siúl le chéile.\n\nCruthaigh bhur dturas féin le cairde.'},{title:'KRAЇNA',body:'— Tá an stair san áit a bhfuil tú anois'}],
  ca:[{title:'Descobreix monuments interessants',body:'A la teva ciutat hi ha molts monuments històrics que et poden interessar per la seva història.'},{title:'Escaneja un monument',body:'Llegeix o escolta una història interessant que no escoltaràs en una visita guiada.\n\nApunta la càmera cap a l\'objecte i espera que es carregui la història.'},{title:'Troba rutes',body:'Et proposarem rutes adaptades a les teves preferències.\n\nTraçarem el camí fins al punt desitjat, i podràs descobrir la història com en una aventura.'},{title:'Comparteix la teva història',body:'Ajuda altres usuaris a descobrir llocs i històries interessants. Publica posts i stories amb una ruta.'},{title:'Xateja amb els teus amics',body:'Troba rutes interessants, comparteix-les amb els teus amics i sortiu a passejar junts.\n\nCreeu la vostra pròpia excursió amb amics.'},{title:'KRAЇNA',body:'— La història és on ets ara'}],
  tr:[{title:'İlginç anıtları keşfet',body:'Şehrinde tarihleriyle seni ilgilendirebilecek birçok tarihi anıt var.'},{title:'Bir anıtı tara',body:'Rehberli turda duymayacağın ilginç bir hikâye oku ya da dinle.\n\nKamerayı nesneye yönelt ve hikâyenin yüklenmesini bekle.'},{title:'Rotalar bul',body:'Sana tercihlerine uyarlanmış rotalar önereceğiz.\n\nİstediğin noktaya kadar yolu çizeriz ve tarihi bir macera gibi keşfedebilirsin.'},{title:'Hikâyeni paylaş',body:'Diğer kullanıcıların ilginç yerler ve hikâyeler keşfetmesine yardım et. Bir rota ile gönderiler ve hikâyeler paylaş.'},{title:'Arkadaşlarınla sohbet et',body:'İlginç rotalar bul, arkadaşlarınla paylaş ve birlikte yürüyüşe çıkın.\n\nArkadaşlarınızla kendi gezinizi oluşturun.'},{title:'KRAЇNA',body:'— Tarih, şu an olduğun yerde'}]
};


